use crate::chart::types::*;

use super::vertex::Vertex;

const LANE_WIDTH: f32 = 1.0;
const TRACK_WIDTH: f32 = 4.0 * LANE_WIDTH;
const TRACK_LENGTH: f32 = 25.0;
const NOTE_WIDTH: f32 = 0.85;
const NOTE_DEPTH: f32 = 0.15;
const NOTE_Y: f32 = 0.01;
const SCROLL_SPEED: f32 = 8.0; // z-units per second of chart time

/// Build all geometry for a static chart view (no scrolling yet).
pub fn build_scene(chart: &Chart) -> (Vec<Vertex>, Vec<u32>) {
    let mut verts = Vec::new();
    let mut idxs = Vec::new();

    build_track(&mut verts, &mut idxs);
    build_lane_dividers(&mut verts, &mut idxs);
    build_judgment_line(&mut verts, &mut idxs);

    for group in &chart.groups {
        for tap in &group.taps {
            build_tap(tap, &mut verts, &mut idxs);
        }
        for hold in &group.holds {
            build_hold(hold, &mut verts, &mut idxs);
        }
        for arc in &group.arcs {
            if arc.is_trace {
                for sn in &arc.sky_notes {
                    build_sky_note(arc, sn, &mut verts, &mut idxs);
                }
            }
        }
    }

    (verts, idxs)
}

fn push_quad(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>, corners: [[f32; 3]; 4], color: [f32; 4]) {
    let base = verts.len() as u32;
    for pos in corners {
        verts.push(Vertex {
            position: pos,
            color,
        });
    }
    idxs.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);
}

fn build_track(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    push_quad(
        verts,
        idxs,
        [
            [0.0, 0.0, 0.0],
            [TRACK_WIDTH, 0.0, 0.0],
            [TRACK_WIDTH, 0.0, TRACK_LENGTH],
            [0.0, 0.0, TRACK_LENGTH],
        ],
        [0.10, 0.10, 0.16, 1.0],
    );
}

fn build_lane_dividers(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let color = [0.22, 0.22, 0.32, 1.0];
    let w = 0.015;
    let y = 0.001;
    for i in 0..=4 {
        let x = i as f32 * LANE_WIDTH;
        push_quad(
            verts,
            idxs,
            [
                [x - w, y, 0.0],
                [x + w, y, 0.0],
                [x + w, y, TRACK_LENGTH],
                [x - w, y, TRACK_LENGTH],
            ],
            color,
        );
    }
}

fn build_judgment_line(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let d = 0.04;
    let y = 0.002;
    push_quad(
        verts,
        idxs,
        [
            [0.0, y, -d],
            [TRACK_WIDTH, y, -d],
            [TRACK_WIDTH, y, d],
            [0.0, y, d],
        ],
        [0.85, 0.25, 0.35, 1.0],
    );
}

fn time_to_z(time_ms: Ms) -> f32 {
    time_ms as f32 / 1000.0 * SCROLL_SPEED
}

fn lane_to_x(lane: f32) -> f32 {
    (lane - 1.0) * LANE_WIDTH + LANE_WIDTH * 0.5
}

fn build_tap(tap: &Tap, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let cx = lane_to_x(tap.lane);
    let z = time_to_z(tap.time);
    let hw = NOTE_WIDTH * 0.5;
    let hd = NOTE_DEPTH * 0.5;
    push_quad(
        verts,
        idxs,
        [
            [cx - hw, NOTE_Y, z - hd],
            [cx + hw, NOTE_Y, z - hd],
            [cx + hw, NOTE_Y, z + hd],
            [cx - hw, NOTE_Y, z + hd],
        ],
        [0.40, 0.60, 1.00, 1.0], // blue
    );
}

fn build_hold(hold: &Hold, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let cx = lane_to_x(hold.lane);
    let z1 = time_to_z(hold.start);
    let z2 = time_to_z(hold.end);
    let hw = NOTE_WIDTH * 0.5;
    push_quad(
        verts,
        idxs,
        [
            [cx - hw, NOTE_Y, z1],
            [cx + hw, NOTE_Y, z1],
            [cx + hw, NOTE_Y, z2],
            [cx - hw, NOTE_Y, z2],
        ],
        [0.30, 0.80, 0.50, 1.0], // green
    );
}

fn build_sky_note(arc: &Arc, sn: &SkyNote, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    // Interpolate arc position at sky note time
    let t = if arc.end > arc.start {
        (sn.time - arc.start) as f32 / (arc.end - arc.start) as f32
    } else {
        0.0
    };
    let x = arc.x1 + (arc.x2 - arc.x1) * t; // linear for now
    let y = arc.y1 + (arc.y2 - arc.y1) * t;

    // Map arc coords to world: x [0,1] → [0, TRACK_WIDTH], y [0,1] → [0, 2.0]
    let wx = x * TRACK_WIDTH;
    let wy = y * 2.0 + 0.1;
    let wz = time_to_z(sn.time);

    let hw = NOTE_WIDTH * 0.5;
    let hd = NOTE_DEPTH * 0.5;
    push_quad(
        verts,
        idxs,
        [
            [wx - hw, wy, wz - hd],
            [wx + hw, wy, wz - hd],
            [wx + hw, wy, wz + hd],
            [wx - hw, wy, wz + hd],
        ],
        [0.90, 0.50, 0.90, 1.0], // purple
    );
}

