1	use std::sync::Arc;
2	use wgpu::util::DeviceExt;
3	use winit::window::Window;
4	
5	use super::camera::{Camera, CameraUniform};
6	use super::vertex::Vertex;
7	use crate::chart::types::Chart;
8	
9	const SHADER: &str = "
10	struct CameraUniform {
11	    view_proj: mat4x4<f32>,
12	};
13	
14	@group(0) @binding(0)
15	var<uniform> camera: CameraUniform;
16	
17	struct VsIn {
18	    @location(0) position: vec3<f32>,
19	    @location(1) color: vec4<f32>,
20	};
21	
22	struct VsOut {
23	    @builtin(position) clip_position: vec4<f32>,
24	    @location(0) color: vec4<f32>,
25	};
26	
27	@vertex
28	fn vs_main(in: VsIn) -> VsOut {
29	    var out: VsOut;
30	    out.clip_position = camera.view_proj * vec4<f32>(in.position, 1.0);
31	    out.color = in.color;
32	    return out;
33	}
34	
35	@fragment
36	fn fs_main(in: VsOut) -> @location(0) vec4<f32> {
37	    return in.color;
38	}
39	";
40	
41	pub struct Gpu {
42	    surface: wgpu::Surface<'static>,
43	    device: wgpu::Device,
44	    queue: wgpu::Queue,
45	    config: wgpu::SurfaceConfiguration,
46	
47	    pipeline: wgpu::RenderPipeline,
48	    depth_view: wgpu::TextureView,
49	
50	    camera: Camera,
51	    camera_buffer: wgpu::Buffer,
52	    camera_bind_group: wgpu::BindGroup,
53	
54	    vertex_buffer: wgpu::Buffer,
55	    index_buffer: wgpu::Buffer,
56	    index_count: u32,
57	}
58	
59	impl Gpu {
60	    pub async fn new(window: Arc<Window>, chart: &Chart) -> Self {
61	        let size = window.inner_size();
62	
63	        let instance = wgpu::Instance::new(wgpu::InstanceDescriptor {
64	            backends: wgpu::Backends::all(),
65	            ..Default::default()
66	        });
67	
68	        let surface = instance
69	            .create_surface(window)
70	            .expect("failed to create surface");
71	
72	        let adapter = instance
73	            .request_adapter(&wgpu::RequestAdapterOptions {
74	                power_preference: wgpu::PowerPreference::HighPerformance,
75	                compatible_surface: Some(&surface),
76	                force_fallback_adapter: false,
77	            })
78	            .await
79	            .expect("no suitable GPU adapter");
80	
81	        log::info!("GPU: {:?}", adapter.get_info());
82	
83	        let limits = if cfg!(target_os = "android") {
84	            wgpu::Limits::downlevel_defaults()
85	        } else {
86	            wgpu::Limits::default()
87	        }
88	        .using_resolution(adapter.limits());
89	
90	        let (device, queue) = adapter
91	            .request_device(
92	                &wgpu::DeviceDescriptor {
93	                    label: Some("better-arc"),
94	                    required_features: wgpu::Features::empty(),
95	                    required_limits: limits,
96	                    ..Default::default()
97	                },
98	                None,
99	            )
100	            .await
101	            .expect("failed to create device");
102	
103	        // Surface
104	        let caps = surface.get_capabilities(&adapter);
105	        let format = caps
106	            .formats
107	            .iter()
108	            .find(|f| f.is_srgb())
109	            .copied()
110	            .unwrap_or(caps.formats[0]);
111	
112	        let config = wgpu::SurfaceConfiguration {
113	            usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
114	            format,
115	            width: size.width.max(1),
116	            height: size.height.max(1),
117	            present_mode: wgpu::PresentMode::AutoVsync,
118	            alpha_mode: caps.alpha_modes[0],
119	            view_formats: vec![],
120	            desired_maximum_frame_latency: 2,
121	        };
122	        surface.configure(&device, &config);
123	
124	        // Shader
125	        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
126	            label: Some("shader"),
127	            source: wgpu::ShaderSource::Wgsl(SHADER.into()),
128	        });
129	
130	        // Camera
131	        let aspect = config.width as f32 / config.height as f32;
132	        let camera = Camera::arcaea_default(aspect);
133	        let camera_uniform = CameraUniform::from(&camera);
134	
135	        let camera_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
136	            label: Some("camera_uniform"),
137	            contents: bytemuck::cast_slice(&[camera_uniform]),
138	            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
139	        });
140	
141	        let camera_bgl = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
142	            label: Some("camera_bgl"),
143	            entries: &[wgpu::BindGroupLayoutEntry {
144	                binding: 0,
145	                visibility: wgpu::ShaderStages::VERTEX,
146	                ty: wgpu::BindingType::Buffer {
147	                    ty: wgpu::BufferBindingType::Uniform,
148	                    has_dynamic_offset: false,
149	                    min_binding_size: None,
150	                },
151	                count: None,
152	            }],
153	        });
154	
155	        let camera_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
156	            label: Some("camera_bg"),
157	            layout: &camera_bgl,
158	            entries: &[wgpu::BindGroupEntry {
159	                binding: 0,
160	                resource: camera_buffer.as_entire_binding(),
161	            }],
162	        });
163	
164	        // Pipeline
165	        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
166	            label: Some("pipeline_layout"),
167	            bind_group_layouts: &[&camera_bgl],
168	            push_constant_ranges: &[],
169	        });
170	
171	        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
172	            label: Some("main"),
173	            layout: Some(&pipeline_layout),
174	            vertex: wgpu::VertexState {
175	                module: &shader,
176	                entry_point: Some("vs_main"),
177	                buffers: &[Vertex::layout()],
178	                compilation_options: Default::default(),
179	            },
180	            fragment: Some(wgpu::FragmentState {
181	                module: &shader,
182	                entry_point: Some("fs_main"),
183	                targets: &[Some(wgpu::ColorTargetState {
184	                    format,
185	                    blend: Some(wgpu::BlendState::ALPHA_BLENDING),
186	                    write_mask: wgpu::ColorWrites::ALL,
187	                })],
188	                compilation_options: Default::default(),
189	            }),
190	            primitive: wgpu::PrimitiveState {
191	                topology: wgpu::PrimitiveTopology::TriangleList,
192	                cull_mode: None,
193	                ..Default::default()
194	            },
195	            depth_stencil: Some(wgpu::DepthStencilState {
196	                format: wgpu::TextureFormat::Depth32Float,
197	                depth_write_enabled: true,
198	                depth_compare: wgpu::CompareFunction::Less,
199	                stencil: wgpu::StencilState::default(),
200	                bias: wgpu::DepthBiasState::default(),
201	            }),
202	            multisample: wgpu::MultisampleState::default(),
203	            multiview: None,
204	            cache: None,
205	        });
206	
207	        // Depth buffer
208	        let depth_view = create_depth_texture(&device, config.width, config.height);
209	
210	        // Scene geometry
211	        let (vertices, indices) = super::track::build_scene(chart);
212	        let index_count = indices.len() as u32;
213	        log::info!(
214	            "scene: {} vertices, {} indices",
215	            vertices.len(),
216	            indices.len()
217	        );
218	
219	        let vertex_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
220	            label: Some("vertices"),
221	            contents: bytemuck::cast_slice(&vertices),
222	            usage: wgpu::BufferUsages::VERTEX,
223	        });
224	
225	        let index_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
226	            label: Some("indices"),
