/// Convert chart time to z-coordinate for static rendering.
/// Uses the Arcaea formula: z = floorPosition / baseBpm * dropRate / -1000
/// For constant BPM (which covers the static view case):
///   floorPosition(t) = t * bpm, so z = t * dropRate / -1000
fn time_to_z(time_ms: Ms, base_bpm: f32, drop_rate: f32) -> f32 {
    // With constant BPM == baseBPM and density_factor == 1.0:
    // floorPosition = time_ms * bpm
    // z = (time_ms * bpm) / bpm * drop_rate / -1000
    //   = time_ms * drop_rate / -1000
