pub fn build_scene(chart: &Chart) -> (Vec<Vertex>, Vec<u32>) {
    let mut verts = Vec::new();
    let mut idxs = Vec::new();

    // Extract base BPM from first timing event
    let base_bpm = chart.groups[0]
        .timings
        .first()
        .map(|t| t.bpm)
        .unwrap_or(120.0);

    build_track(&mut verts, &mut idxs);
    build_lane_dividers(&mut verts, &mut idxs);
    build_judgment_line(&mut verts, &mut idxs);

    for group in &chart.groups {
        for tap in &group.taps {
            build_tap(tap, base_bpm, &mut verts, &mut idxs);
        }
        for hold in &group.holds {
            build_hold(hold, base_bpm, &mut verts, &mut idxs);
        }
        for arc in &group.arcs {
            // Render arc body (line segments)
            build_arc_body(arc, base_bpm, &mut verts, &mut idxs);
            // Render sky notes on traces
            if arc.is_trace {
                for sn in &arc.sky_notes {
                    build_sky_note(arc, sn, base_bpm, &mut verts, &mut idxs);
                }
            }
        }
    }

    (verts, idxs)
}
```

