fn build_sky_note(arc: &Arc, sn: &SkyNote, base_bpm: f32, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    // Interpolate arc position at sky note time (linear for now)
    let t = if arc.end > arc.start {
        (sn.time - arc.start) as f32 / (arc.end - arc.start) as f32
    } else {
        0.0
    };
    let x = arc.x1 + (arc.x2 - arc.x1) * t;
    let y = arc.y1 + (arc.y2 - arc.y1) * t;

    // Correct arc coordinate mapping
    let wx = arc_x_to_world(x);
    let wy = arc_y_to_world(y);
    let wz = time_to_z(sn.time, base_bpm, DEFAULT_DROP_RATE);

    // Sky note dimensions from .obj extraction, scaled by note_scale_at_z
    let scale = note_scale_at_z(wz);
    let hw = SKY_NOTE_WIDTH * scale * 0.5;
    let hd = SKY_NOTE_DEPTH * scale * 0.5;
    let hh = SKY_NOTE_HEIGHT * scale * 0.5;

    // Sky notes are vertical quads (face the camera), not flat on ground
    // For static view, render as a horizontal quad at the correct Y height
    push_quad(
        verts,
        idxs,
        [
            [wx - hw, wy, wz - hd],
            [wx + hw, wy, wz - hd],
            [wx + hw, wy, wz + hd],
            [wx - hw, wy, wz + hd],
        ],
        [0.90, 0.50, 0.90, 1.0],
    );
}
