use crate::chart::types::*;

use super::vertex::Vertex;

// RE-confirmed track parameters (Arcaea 6.13.10c)
const LANE_WIDTH: f32 = 4.25;
const TRACK_WIDTH: f32 = 4.0 * LANE_WIDTH; // 17.0
const TRACK_HALF_WIDTH: f32 = TRACK_WIDTH / 2.0; // 8.5
const TRACK_LENGTH_FORWARD: f32 = 100.0; // z=0 to z=-100
const TRACK_LENGTH_BACKWARD: f32 = 53.5; // z=0 to z=+53.5

// Sky note dimensions (from .obj extraction)
const SKY_NOTE_WIDTH: f32 = 1.17;
const SKY_NOTE_DEPTH: f32 = 0.20;

const NOTE_Y: f32 = 0.01;

// Arc body rendering
const ARC_BODY_WIDTH: f32 = 0.9;
const TRACE_BODY_WIDTH: f32 = 0.15;
const ARC_SEGMENT_MS: f32 = 71.4; // 1000/14 ms per segment

// Static preview drop rate (spreads test chart across visible range)
const DEFAULT_DROP_RATE: f32 = 10.0;

/// Build all geometry for a static chart view (no scrolling yet).
pub fn build_scene(chart: &Chart) -> (Vec<Vertex>, Vec<u32>) {
    let mut verts = Vec::new();
    let mut idxs = Vec::new();

    build_track(&mut verts, &mut idxs);
    build_lane_dividers(&mut verts, &mut idxs);
    build_judgment_line(&mut verts, &mut idxs);

    for group in &chart.groups {
        for tap in &group.taps {
            build_tap(tap, &mut verts, &mut idxs);
        }
        for hold in &group.holds {
            build_hold(hold, &mut verts, &mut idxs);
        }
        for arc in &group.arcs {
            build_arc_body(arc, &mut verts, &mut idxs);
            if arc.is_trace {
                for sn in &arc.sky_notes {
                    build_sky_note(arc, sn, &mut verts, &mut idxs);
                }
            }
        }
    }

    (verts, idxs)
}

fn push_quad(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>, corners: [[f32; 3]; 4], color: [f32; 4]) {
    let base = verts.len() as u32;
    for pos in corners {
        verts.push(Vertex {
            position: pos,
            color,
        });
    }
    idxs.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);
}

fn build_track(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    push_quad(
        verts,
        idxs,
        [
            [-TRACK_HALF_WIDTH, 0.0, TRACK_LENGTH_BACKWARD],
            [TRACK_HALF_WIDTH, 0.0, TRACK_LENGTH_BACKWARD],
            [TRACK_HALF_WIDTH, 0.0, -TRACK_LENGTH_FORWARD],
            [-TRACK_HALF_WIDTH, 0.0, -TRACK_LENGTH_FORWARD],
        ],
        [0.10, 0.10, 0.16, 1.0],
    );
}

fn build_lane_dividers(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let color = [0.22, 0.22, 0.32, 1.0];
    let w = 0.04;
    let y = 0.001;
    // Lane boundaries: +8.5, +4.25, 0.0, -4.25, -8.5
    for &x in &[
        TRACK_HALF_WIDTH,
        TRACK_HALF_WIDTH - LANE_WIDTH,
        0.0,
        -(TRACK_HALF_WIDTH - LANE_WIDTH),
        -TRACK_HALF_WIDTH,
    ] {
        push_quad(
            verts,
            idxs,
            [
                [x - w, y, TRACK_LENGTH_BACKWARD],
                [x + w, y, TRACK_LENGTH_BACKWARD],
                [x + w, y, -TRACK_LENGTH_FORWARD],
                [x - w, y, -TRACK_LENGTH_FORWARD],
            ],
            color,
        );
    }
}

fn build_judgment_line(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let d = 0.15;
    let y = 0.002;
    push_quad(
        verts,
        idxs,
        [
            [-TRACK_HALF_WIDTH, y, -d],
            [TRACK_HALF_WIDTH, y, -d],
            [TRACK_HALF_WIDTH, y, d],
            [-TRACK_HALF_WIDTH, y, d],
        ],
        [0.85, 0.25, 0.35, 1.0],
    );
}

/// z = time_ms * dropRate / -1000 (constant-BPM simplification)
fn time_to_z(time_ms: Ms) -> f32 {
    time_ms as f32 * DEFAULT_DROP_RATE / -1000.0
}

/// LaneToWorldX(lane) = -4.25 * lane + 10.625
fn lane_to_x(lane: f32) -> f32 {
    -LANE_WIDTH * lane + LANE_WIDTH * 2.5
}

/// ArcXToWorld(x) = -8.5 * x + 4.25
fn arc_x_to_world(x: f32) -> f32 {
    -TRACK_HALF_WIDTH * x + LANE_WIDTH
}

/// ArcYToWorld(y) = 1.0 + 4.5 * y
fn arc_y_to_world(y: f32) -> f32 {
    1.0 + 4.5 * y
}

/// Note scale factor by z-position (compensates perspective foreshortening).
/// At z=0: 1.5, grows with distance.
fn note_scale_at_z(z: f32) -> f32 {
    if z <= 0.0 {
        (1.5 + 6.25 * (-z) / 100.0).abs()
    } else {
        (1.5 + 7.25 * z / 53.5).abs()
    }
}

fn build_tap(tap: &Tap, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let cx = lane_to_x(tap.lane);
    let z = time_to_z(tap.time);
    let scale = note_scale_at_z(z);
    let hw = scale * 0.5;
    let hd = scale * 0.1;
    push_quad(
        verts,
        idxs,
        [
            [cx - hw, NOTE_Y, z - hd],
            [cx + hw, NOTE_Y, z - hd],
            [cx + hw, NOTE_Y, z + hd],
            [cx - hw, NOTE_Y, z + hd],
        ],
        [0.40, 0.60, 1.00, 1.0], // blue
    );
}

fn build_hold(hold: &Hold, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let cx = lane_to_x(hold.lane);
    let z1 = time_to_z(hold.start);
    let z2 = time_to_z(hold.end);
    let scale = note_scale_at_z(z1);
    let hw = scale * 0.5;
    push_quad(
        verts,
        idxs,
        [
            [cx - hw, NOTE_Y, z1],
            [cx + hw, NOTE_Y, z1],
