100	fn build_track(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
101	    push_quad(
102	        verts,
103	        idxs,
104	        [
105	            [-TRACK_HALF_WIDTH, 0.0, TRACK_LENGTH_BACKWARD],
106	            [TRACK_HALF_WIDTH, 0.0, TRACK_LENGTH_BACKWARD],
107	            [TRACK_HALF_WIDTH, 0.0, -TRACK_LENGTH_FORWARD],
108	            [-TRACK_HALF_WIDTH, 0.0, -TRACK_LENGTH_FORWARD],
109	        ],
110	        [0.10, 0.10, 0.16, 1.0],
111	    );
