119	    for &x in &[
120	        TRACK_HALF_WIDTH,
121	        TRACK_HALF_WIDTH - LANE_WIDTH,
122	        0.0,
123	        -(TRACK_HALF_WIDTH - LANE_WIDTH),
124	        -TRACK_HALF_WIDTH,
