126	        push_quad(
127	            verts,
128	            idxs,
129	            [
130	                [x - w, y, TRACK_LENGTH_BACKWARD],
131	                [x + w, y, TRACK_LENGTH_BACKWARD],
132	                [x + w, y, -TRACK_LENGTH_FORWARD],
133	                [x - w, y, -TRACK_LENGTH_FORWARD],
134	            ],
