184	    let hw = scale * 0.5;
185	    let hd = scale * 0.1;
186	    push_quad(
187	        verts,
188	        idxs,
189	        [
190	            [cx - hw, NOTE_Y, z - hd],
191	            [cx + hw, NOTE_Y, z - hd],
192	            [cx + hw, NOTE_Y, z + hd],
193	            [cx - hw, NOTE_Y, z + hd],
194	        ],
