199	fn build_hold(hold: &Hold, z1: f32, z2: f32, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
200	    let cx = lane_to_x(hold.lane);
201	    let scale = note_scale_at_z(z1);
202	    let hw = scale * 0.5;
203	    push_quad(
204	        verts,
205	        idxs,
206	        [
207	            [cx - hw, NOTE_Y, z1],
208	            [cx + hw, NOTE_Y, z1],
209	            [cx + hw, NOTE_Y, z2],
210	            [cx - hw, NOTE_Y, z2],
211	        ],
212	        [0.30, 0.80, 0.50, 1.0], // green
213	    );
214	}
