216	fn build_sky_note(arc: &Arc, sn: &SkyNote, wz: f32, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
217	    // Interpolate arc position at sky note time (linear for now)
218	    let t = if arc.end > arc.start {
219	        (sn.time - arc.start) as f32 / (arc.end - arc.start) as f32
220	    } else {
221	        0.0
222	    };
223	    let x = arc.x1 + (arc.x2 - arc.x1) * t;
224	    let y = arc.y1 + (arc.y2 - arc.y1) * t;
225	
226	    let wx = arc_x_to_world(x);
227	    let wy = arc_y_to_world(y);
228	
229	    let scale = note_scale_at_z(wz);
230	    let hw = SKY_NOTE_WIDTH * scale * 0.5;
231	    let hd = SKY_NOTE_DEPTH * scale * 0.5;
232	    push_quad(
233	        verts,
234	        idxs,
235	        [
236	            [wx - hw, wy, wz - hd],
237	            [wx + hw, wy, wz - hd],
238	            [wx + hw, wy, wz + hd],
239	            [wx - hw, wy, wz + hd],
240	        ],
241	        [0.90, 0.50, 0.90, 1.0], // purple
242	    );
243	}
244	
245	fn build_arc_body(
246	    arc: &Arc,
247	    clock: &GameClock,
248	    current_time: Ms,
249	    verts: &mut Vec<Vertex>,
250	    idxs: &mut Vec<u32>,
251	) {
252	    let duration_ms = (arc.end - arc.start) as f32;
253	    if duration_ms <= 0.0 {
254	        return;
255	    }
256	
257	    let num_segments = ((duration_ms / ARC_SEGMENT_MS).ceil() as usize).max(1);
258	
259	    let color = if arc.is_trace {
260	        [0.40, 0.40, 0.50, 0.48]
261	    } else if arc.color == 0 {
262	        [0.30, 0.50, 1.00, 0.88] // blue
263	    } else {
264	        [1.00, 0.35, 0.45, 0.88] // red
265	    };
266	
267	    let body_width = if arc.is_trace {
268	        TRACE_BODY_WIDTH
269	    } else {
270	        ARC_BODY_WIDTH
271	    };
272	
273	    for i in 0..num_segments {
274	        let t0 = i as f32 / num_segments as f32;
275	        let t1 = (i + 1) as f32 / num_segments as f32;
276	
277	        // Linear interpolation (proper easing is Phase 4)
278	        let x0 = arc.x1 + (arc.x2 - arc.x1) * t0;
279	        let y0 = arc.y1 + (arc.y2 - arc.y1) * t0;
280	        let x1 = arc.x1 + (arc.x2 - arc.x1) * t1;
281	        let y1 = arc.y1 + (arc.y2 - arc.y1) * t1;
282	
283	        let time0 = arc.start + (duration_ms * t0) as i32;
284	        let time1 = arc.start + (duration_ms * t1) as i32;
285	
286	        let wx0 = arc_x_to_world(x0);
287	        let wy0 = arc_y_to_world(y0);
288	        let wz0 = clock.time_to_z(time0, current_time, DROP_RATE);
289	
290	        let wx1 = arc_x_to_world(x1);
291	        let wy1 = arc_y_to_world(y1);
292	        let wz1 = clock.time_to_z(time1, current_time, DROP_RATE);
293	
294	        // Cull segments outside visible range
295	        if wz0 > TRACK_LENGTH_BACKWARD && wz1 > TRACK_LENGTH_BACKWARD {
296	            continue;
297	        }
298	        if wz0 < -TRACK_LENGTH_FORWARD && wz1 < -TRACK_LENGTH_FORWARD {
299	            continue;
300	        }
301	
302	        let hw = body_width * 0.5;
303	
304	        push_quad(
305	            verts,
306	            idxs,
307	            [
308	                [wx0 - hw, wy0, wz0],
309	                [wx0 + hw, wy0, wz0],
310	                [wx1 + hw, wy1, wz1],
311	                [wx1 - hw, wy1, wz1],
312	            ],
313	            color,
314	        );
315	    }
316	}
