use crate::chart::types::*;
use crate::timing::GameClock;

use super::vertex::Vertex;

// RE-confirmed track parameters (Arcaea 6.13.10c)
const LANE_WIDTH: f32 = 4.25;
const TRACK_WIDTH: f32 = 4.0 * LANE_WIDTH; // 17.0
const TRACK_HALF_WIDTH: f32 = TRACK_WIDTH / 2.0; // 8.5
const TRACK_LENGTH_FORWARD: f32 = 100.0; // z=0 to z=-100
const TRACK_LENGTH_BACKWARD: f32 = 53.5; // z=0 to z=+53.5

// Sky note dimensions (from .obj extraction)
const SKY_NOTE_WIDTH: f32 = 1.17;
const SKY_NOTE_DEPTH: f32 = 0.20;

const NOTE_Y: f32 = 0.01;

// Arc body rendering
const ARC_BODY_WIDTH: f32 = 0.9;
const TRACE_BODY_WIDTH: f32 = 0.15;
const ARC_SEGMENT_MS: f32 = 71.4; // 1000/14 ms per segment

/// User speed setting (will be configurable later).
const DROP_RATE: f32 = 3.5;

/// Build static track geometry (track surface, lane dividers, judgment line).
/// Created once at init.
pub fn build_track_geometry() -> (Vec<Vertex>, Vec<u32>) {
    let mut verts = Vec::new();
    let mut idxs = Vec::new();

    build_track(&mut verts, &mut idxs);
    build_lane_dividers(&mut verts, &mut idxs);
    build_judgment_line(&mut verts, &mut idxs);

    (verts, idxs)
}

/// Build note geometry for the current frame. Notes are positioned relative
/// to current_time so the judgment line always corresponds to "now".
pub fn build_note_geometry(
    chart: &Chart,
    clock: &GameClock,
    current_time: Ms,
) -> (Vec<Vertex>, Vec<u32>) {
    let mut verts = Vec::new();
    let mut idxs = Vec::new();

    for group in &chart.groups {
        for tap in &group.taps {
            let z = clock.time_to_z(tap.time, current_time, DROP_RATE);
            if z < -TRACK_LENGTH_FORWARD || z > TRACK_LENGTH_BACKWARD {
                continue;
            }
            build_tap(tap, z, &mut verts, &mut idxs);
        }
        for hold in &group.holds {
            let z1 = clock.time_to_z(hold.start, current_time, DROP_RATE);
            let z2 = clock.time_to_z(hold.end, current_time, DROP_RATE);
            // Skip if entirely out of visible range
            if z2 > TRACK_LENGTH_BACKWARD || z1 < -TRACK_LENGTH_FORWARD {
                continue;
            }
            build_hold(hold, z1, z2, &mut verts, &mut idxs);
        }
        for arc in &group.arcs {
            let z_start = clock.time_to_z(arc.start, current_time, DROP_RATE);
            let z_end = clock.time_to_z(arc.end, current_time, DROP_RATE);
            if z_end > TRACK_LENGTH_BACKWARD || z_start < -TRACK_LENGTH_FORWARD {
                continue;
            }
            build_arc_body(arc, clock, current_time, &mut verts, &mut idxs);
            if arc.is_trace {
                for sn in &arc.sky_notes {
                    let z = clock.time_to_z(sn.time, current_time, DROP_RATE);
                    if z < -TRACK_LENGTH_FORWARD || z > TRACK_LENGTH_BACKWARD {
                        continue;
                    }
                    build_sky_note(arc, sn, z, &mut verts, &mut idxs);
                }
            }
        }
    }

    (verts, idxs)
}

fn push_quad(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>, corners: [[f32; 3]; 4], color: [f32; 4]) {
    let base = verts.len() as u32;
    for pos in corners {
        verts.push(Vertex {
            position: pos,
            color,
        });
    }
    idxs.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);
}

fn build_track(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    push_quad(
        verts,
        idxs,
        [
            [-TRACK_HALF_WIDTH, 0.0, TRACK_LENGTH_BACKWARD],
            [TRACK_HALF_WIDTH, 0.0, TRACK_LENGTH_BACKWARD],
            [TRACK_HALF_WIDTH, 0.0, -TRACK_LENGTH_FORWARD],
            [-TRACK_HALF_WIDTH, 0.0, -TRACK_LENGTH_FORWARD],
        ],
        [0.10, 0.10, 0.16, 1.0],
    );
}

fn build_lane_dividers(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let color = [0.22, 0.22, 0.32, 1.0];
    let w = 0.04;
    let y = 0.001;
    // Lane boundaries: +8.5, +4.25, 0.0, -4.25, -8.5
    for &x in &[
        TRACK_HALF_WIDTH,
        TRACK_HALF_WIDTH - LANE_WIDTH,
        0.0,
        -(TRACK_HALF_WIDTH - LANE_WIDTH),
        -TRACK_HALF_WIDTH,
    ] {
        push_quad(
            verts,
            idxs,
            [
                [x - w, y, TRACK_LENGTH_BACKWARD],
                [x + w, y, TRACK_LENGTH_BACKWARD],
                [x + w, y, -TRACK_LENGTH_FORWARD],
                [x - w, y, -TRACK_LENGTH_FORWARD],
            ],
            color,
        );
    }
}

fn build_judgment_line(verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let d = 0.15;
    let y = 0.002;
    push_quad(
        verts,
        idxs,
        [
            [-TRACK_HALF_WIDTH, y, -d],
            [TRACK_HALF_WIDTH, y, -d],
            [TRACK_HALF_WIDTH, y, d],
            [-TRACK_HALF_WIDTH, y, d],
        ],
        [0.85, 0.25, 0.35, 1.0],
    );
}

/// LaneToWorldX(lane) = -4.25 * lane + 10.625
fn lane_to_x(lane: f32) -> f32 {
    -LANE_WIDTH * lane + LANE_WIDTH * 2.5
}

/// ArcXToWorld(x) = -8.5 * x + 4.25
fn arc_x_to_world(x: f32) -> f32 {
    -TRACK_HALF_WIDTH * x + LANE_WIDTH
}

/// ArcYToWorld(y) = 1.0 + 4.5 * y
fn arc_y_to_world(y: f32) -> f32 {
    1.0 + 4.5 * y
}

/// Note scale factor by z-position (compensates perspective foreshortening).
/// At z=0: 1.5, grows with distance.
fn note_scale_at_z(z: f32) -> f32 {
    if z <= 0.0 {
        (1.5 + 6.25 * (-z) / 100.0).abs()
    } else {
        (1.5 + 7.25 * z / 53.5).abs()
    }
}

fn build_tap(tap: &Tap, z: f32, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let cx = lane_to_x(tap.lane);
    let scale = note_scale_at_z(z);
    let hw = scale * 0.5;
    let hd = scale * 0.1;
    push_quad(
        verts,
        idxs,
        [
            [cx - hw, NOTE_Y, z - hd],
            [cx + hw, NOTE_Y, z - hd],
            [cx + hw, NOTE_Y, z + hd],
            [cx - hw, NOTE_Y, z + hd],
        ],
        [0.40, 0.60, 1.00, 1.0], // blue
    );
}

fn build_hold(hold: &Hold, z1: f32, z2: f32, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    let cx = lane_to_x(hold.lane);
    let scale = note_scale_at_z(z1);
    let hw = scale * 0.5;
    push_quad(
        verts,
        idxs,
        [
            [cx - hw, NOTE_Y, z1],
            [cx + hw, NOTE_Y, z1],
            [cx + hw, NOTE_Y, z2],
            [cx - hw, NOTE_Y, z2],
        ],
        [0.30, 0.80, 0.50, 1.0], // green
    );
}

fn build_sky_note(arc: &Arc, sn: &SkyNote, wz: f32, verts: &mut Vec<Vertex>, idxs: &mut Vec<u32>) {
    // Interpolate arc position at sky note time (linear for now)
    let t = if arc.end > arc.start {
        (sn.time - arc.start) as f32 / (arc.end - arc.start) as f32
    } else {
        0.0
    };
    let x = arc.x1 + (arc.x2 - arc.x1) * t;
    let y = arc.y1 + (arc.y2 - arc.y1) * t;

    let wx = arc_x_to_world(x);
    let wy = arc_y_to_world(y);

    let scale = note_scale_at_z(wz);
    let hw = SKY_NOTE_WIDTH * scale * 0.5;
    let hd = SKY_NOTE_DEPTH * scale * 0.5;
    push_quad(
        verts,
        idxs,
        [
            [wx - hw, wy, wz - hd],
            [wx + hw, wy, wz - hd],
            [wx + hw, wy, wz + hd],
            [wx - hw, wy, wz + hd],
        ],
        [0.90, 0.50, 0.90, 1.0], // purple
    );
}

fn build_arc_body(
    arc: &Arc,
    clock: &GameClock,
    current_time: Ms,
    verts: &mut Vec<Vertex>,
    idxs: &mut Vec<u32>,
) {
    let duration_ms = (arc.end - arc.start) as f32;
    if duration_ms <= 0.0 {
        return;
    }

    let num_segments = ((duration_ms / ARC_SEGMENT_MS).ceil() as usize).max(1);

    let color = if arc.is_trace {
        [0.40, 0.40, 0.50, 0.48]
    } else if arc.color == 0 {
        [0.30, 0.50, 1.00, 0.88] // blue
    } else {
        [1.00, 0.35, 0.45, 0.88] // red
    };

    let body_width = if arc.is_trace {
        TRACE_BODY_WIDTH
    } else {
        ARC_BODY_WIDTH
    };

    for i in 0..num_segments {
        let t0 = i as f32 / num_segments as f32;
        let t1 = (i + 1) as f32 / num_segments as f32;

        // Linear interpolation (proper easing is Phase 4)
        let x0 = arc.x1 + (arc.x2 - arc.x1) * t0;
        let y0 = arc.y1 + (arc.y2 - arc.y1) * t0;
        let x1 = arc.x1 + (arc.x2 - arc.x1) * t1;
        let y1 = arc.y1 + (arc.y2 - arc.y1) * t1;

        let time0 = arc.start + (duration_ms * t0) as i32;
        let time1 = arc.start + (duration_ms * t1) as i32;

        let wx0 = arc_x_to_world(x0);
        let wy0 = arc_y_to_world(y0);
        let wz0 = clock.time_to_z(time0, current_time, DROP_RATE);

        let wx1 = arc_x_to_world(x1);
        let wy1 = arc_y_to_world(y1);
        let wz1 = clock.time_to_z(time1, current_time, DROP_RATE);

        // Cull segments outside visible range
        if wz0 > TRACK_LENGTH_BACKWARD && wz1 > TRACK_LENGTH_BACKWARD {
            continue;
        }
        if wz0 < -TRACK_LENGTH_FORWARD && wz1 < -TRACK_LENGTH_FORWARD {
            continue;
        }

        let hw = body_width * 0.5;

        push_quad(
            verts,
            idxs,
            [
                [wx0 - hw, wy0, wz0],
                [wx0 + hw, wy0, wz0],
                [wx1 + hw, wy1, wz1],
                [wx1 - hw, wy1, wz1],
            ],
            color,
        );
    }
}

