use std::path::Path;
use std::sync::Arc;
use wgpu::util::DeviceExt;
use winit::window::Window;

use super::camera::{Camera, CameraUniform};
use super::texture;
use super::track::{NoteGeometry, TrackGeometry};
use super::vertex::Vertex;
use crate::chart::types::{Chart, Ms};
use crate::timing::GameClock;

const SHADER: &str = "
struct CameraUniform {
    view_proj: mat4x4<f32>,
};

@group(0) @binding(0)
var<uniform> camera: CameraUniform;

@group(1) @binding(0)
var tex: texture_2d<f32>;
@group(1) @binding(1)
var tex_sampler: sampler;

struct VsIn {
    @location(0) position: vec3<f32>,
    @location(1) color: vec4<f32>,
    @location(2) uv: vec2<f32>,
};

struct VsOut {
    @builtin(position) clip_position: vec4<f32>,
    @location(0) color: vec4<f32>,
    @location(1) uv: vec2<f32>,
};

@vertex
fn vs_main(in: VsIn) -> VsOut {
    var out: VsOut;
    out.clip_position = camera.view_proj * vec4<f32>(in.position, 1.0);
    out.color = in.color;
    out.uv = in.uv;
    return out;
}

@fragment
fn fs_main(in: VsOut) -> @location(0) vec4<f32> {
    let tex_color = textureSample(tex, tex_sampler, in.uv);
    return tex_color * in.color;
}
";

/// A GPU buffer pair for geometry.
struct MeshBuffer {
    vertex: wgpu::Buffer,
    index: wgpu::Buffer,
    index_count: u32,
}

pub struct Gpu {
    surface: wgpu::Surface<'static>,
    device: wgpu::Device,
    queue: wgpu::Queue,
    config: wgpu::SurfaceConfiguration,

    pipeline: wgpu::RenderPipeline,
    depth_view: wgpu::TextureView,

    camera: Camera,
    camera_buffer: wgpu::Buffer,
    camera_bind_group: wgpu::BindGroup,

    // Textures (bind group per texture)
    tex_white: wgpu::BindGroup,
    tex_track: wgpu::BindGroup,
    tex_note: wgpu::BindGroup,
    tex_hold: wgpu::BindGroup,
    tex_bgl: wgpu::BindGroupLayout,

    // Static geometry
    track_surface: MeshBuffer,
    track_lines: MeshBuffer,

    // Dynamic geometry (rebuilt each frame)
    note_taps: MeshBuffer,
    note_holds: MeshBuffer,
    note_other: MeshBuffer,
}

fn create_mesh_buffer(device: &wgpu::Device, verts: &[Vertex], idxs: &[u32], label: &str) -> MeshBuffer {
    let vertex = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some(&format!("{label}_verts")),
        contents: bytemuck::cast_slice(verts),
        usage: wgpu::BufferUsages::VERTEX,
    });
    let index = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some(&format!("{label}_idxs")),
        contents: bytemuck::cast_slice(idxs),
        usage: wgpu::BufferUsages::INDEX,
    });
    MeshBuffer {
        vertex,
        index,
        index_count: idxs.len() as u32,
    }
}

fn create_dynamic_buffer(device: &wgpu::Device, label: &str) -> MeshBuffer {
    let vertex = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some(&format!("{label}_verts")),
        size: (500 * 4 * std::mem::size_of::<Vertex>()) as u64,
        usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let index = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some(&format!("{label}_idxs")),
        size: (500 * 6 * std::mem::size_of::<u32>()) as u64,
        usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    MeshBuffer {
        vertex,
        index,
        index_count: 0,
    }
}

impl Gpu {
    pub async fn new(window: Arc<Window>, assets_dir: &Path) -> Self {
        let size = window.inner_size();

        let instance = wgpu::Instance::new(wgpu::InstanceDescriptor {
            backends: wgpu::Backends::all(),
            ..Default::default()
        });

        let surface = instance
            .create_surface(window)
            .expect("failed to create surface");

        let adapter = instance
            .request_adapter(&wgpu::RequestAdapterOptions {
                power_preference: wgpu::PowerPreference::HighPerformance,
                compatible_surface: Some(&surface),
                force_fallback_adapter: false,
            })
            .await
            .expect("no suitable GPU adapter");

        log::info!("GPU: {:?}", adapter.get_info());

        let limits = if cfg!(target_os = "android") {
            wgpu::Limits::downlevel_defaults()
        } else {
            wgpu::Limits::default()
        }
        .using_resolution(adapter.limits());

        let (device, queue) = adapter
            .request_device(
                &wgpu::DeviceDescriptor {
                    label: Some("better-arc"),
                    required_features: wgpu::Features::empty(),
                    required_limits: limits,
                    ..Default::default()
                },
                None,
            )
            .await
            .expect("failed to create device");

        // Surface
        let caps = surface.get_capabilities(&adapter);
        let format = caps
            .formats
            .iter()
            .find(|f| f.is_srgb())
            .copied()
            .unwrap_or(caps.formats[0]);

        let config = wgpu::SurfaceConfiguration {
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
            format,
            width: size.width.max(1),
            height: size.height.max(1),
            present_mode: wgpu::PresentMode::AutoVsync,
            alpha_mode: caps.alpha_modes[0],
            view_formats: vec![],
            desired_maximum_frame_latency: 2,
        };
        surface.configure(&device, &config);

        // Shader
        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("shader"),
            source: wgpu::ShaderSource::Wgsl(SHADER.into()),
        });

        // Camera
        let aspect = config.width as f32 / config.height as f32;
        let camera = Camera::arcaea_default(aspect);
        let camera_uniform = CameraUniform::from(&camera);

        let camera_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("camera_uniform"),
            contents: bytemuck::cast_slice(&[camera_uniform]),
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        });

        let camera_bgl = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("camera_bgl"),
            entries: &[wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::VERTEX,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            }],
        });

        let camera_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("camera_bg"),
            layout: &camera_bgl,
            entries: &[wgpu::BindGroupEntry {
                binding: 0,
                resource: camera_buffer.as_entire_binding(),
            }],
        });

        // Textures
        let tex_bgl = texture::texture_bind_group_layout(&device);
        let tex_white = texture::white_texture(&device, &queue, &tex_bgl);

        let extracted = assets_dir.join("extracted");
        let tex_track = if extracted.join("track.png").exists() {
            texture::load_texture(&device, &queue, &tex_bgl, &extracted.join("track.png"), "track")
        } else {
            log::warn!("track.png not found, using white fallback");
            texture::white_texture(&device, &queue, &tex_bgl)
        };
        let tex_note = if extracted.join("note.png").exists() {
            texture::load_texture(&device, &queue, &tex_bgl, &extracted.join("note.png"), "note")
        } else {
            log::warn!("note.png not found, using white fallback");
            texture::white_texture(&device, &queue, &tex_bgl)
        };
        let tex_hold = if extracted.join("note_hold.png").exists() {
            texture::load_texture(
                &device,
                &queue,
                &tex_bgl,
                &extracted.join("note_hold.png"),
                "note_hold",
            )
        } else {
            log::warn!("note_hold.png not found, using white fallback");
            texture::white_texture(&device, &queue, &tex_bgl)
        };

        // Pipeline (now with texture bind group)
        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("pipeline_layout"),
            bind_group_layouts: &[&camera_bgl, &tex_bgl],
            push_constant_ranges: &[],
        });

        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("main"),
            layout: Some(&pipeline_layout),
            vertex: wgpu::VertexState {
                module: &shader,
                entry_point: Some("vs_main"),
                buffers: &[Vertex::layout()],
                compilation_options: Default::default(),
            },
            fragment: Some(wgpu::FragmentState {
                module: &shader,
                entry_point: Some("fs_main"),
                targets: &[Some(wgpu::ColorTargetState {
                    format,
                    blend: Some(wgpu::BlendState::ALPHA_BLENDING),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
                compilation_options: Default::default(),
            }),
            primitive: wgpu::PrimitiveState {
                topology: wgpu::PrimitiveTopology::TriangleList,
                cull_mode: None,
                ..Default::default()
            },
            depth_stencil: Some(wgpu::DepthStencilState {
                format: wgpu::TextureFormat::Depth32Float,
                depth_write_enabled: true,
                depth_compare: wgpu::CompareFunction::Less,
                stencil: wgpu::StencilState::default(),
                bias: wgpu::DepthBiasState::default(),
            }),
            multisample: wgpu::MultisampleState::default(),
            multiview: None,
            cache: None,
        });

        // Depth buffer
        let depth_view = create_depth_texture(&device, config.width, config.height);

        // Static geometry
        let track_geo = super::track::build_track_geometry();
        let track_surface = create_mesh_buffer(&device, &track_geo.surface.0, &track_geo.surface.1, "track_surface");
        let track_lines = create_mesh_buffer(&device, &track_geo.lines.0, &track_geo.lines.1, "track_lines");

        log::info!(
            "static: surface={} idxs, lines={} idxs",
            track_surface.index_count,
            track_lines.index_count
        );

        // Dynamic note buffers (pre-allocated, filled each frame)
        let note_taps = create_dynamic_buffer(&device, "note_taps");
        let note_holds = create_dynamic_buffer(&device, "note_holds");
        let note_other = create_dynamic_buffer(&device, "note_other");

        Self {
            surface,
            device,
            queue,
            config,
            pipeline,
            depth_view,
            camera,
            camera_buffer,
            camera_bind_group,
            tex_white,
            tex_track,
            tex_note,
            tex_hold,
            tex_bgl,
            track_surface,
            track_lines,
            note_taps,
            note_holds,
            note_other,
        }
    }

    /// Update note geometry for the current frame.
    pub fn update_notes(&mut self, chart: &Chart, clock: &GameClock, current_time: Ms) {
        let geo = super::track::build_note_geometry(chart, clock, current_time);
        self.upload_mesh(&geo.taps, "note_taps");
        self.upload_mesh(&geo.holds, "note_holds");
        self.upload_mesh(&geo.other, "note_other");
    }

    fn upload_mesh(&mut self, mesh: &(Vec<Vertex>, Vec<u32>), which: &str) {
        let (verts, idxs) = mesh;
        let buf = match which {
            "note_taps" => &mut self.note_taps,
            "note_holds" => &mut self.note_holds,
            "note_other" => &mut self.note_other,
            _ => return,
        };
        buf.index_count = idxs.len() as u32;

        if verts.is_empty() {
            return;
        }

        let vert_bytes = bytemuck::cast_slice(verts);
        let idx_bytes = bytemuck::cast_slice(idxs);

        if vert_bytes.len() as u64 > buf.vertex.size() {
            buf.vertex = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                label: Some(&format!("{which}_verts")),
                contents: vert_bytes,
                usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
            });
        } else {
            self.queue.write_buffer(&buf.vertex, 0, vert_bytes);
        }

        if idx_bytes.len() as u64 > buf.index.size() {
            buf.index = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                label: Some(&format!("{which}_idxs")),
                contents: idx_bytes,
                usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
            });
        } else {
            self.queue.write_buffer(&buf.index, 0, idx_bytes);
        }
    }

    pub fn resize(&mut self, width: u32, height: u32) {
        self.config.width = width;
        self.config.height = height;
        self.surface.configure(&self.device, &self.config);
        self.depth_view = create_depth_texture(&self.device, width, height);

        self.camera.aspect = width as f32 / height as f32;
        let uniform = CameraUniform::from(&self.camera);
        self.queue
            .write_buffer(&self.camera_buffer, 0, bytemuck::cast_slice(&[uniform]));
    }

    pub fn render(&self) {
        let output = match self.surface.get_current_texture() {
            Ok(t) => t,
            Err(wgpu::SurfaceError::Lost | wgpu::SurfaceError::Outdated) => {
                self.surface.configure(&self.device, &self.config);
                return;
            }
            Err(e) => {
                log::error!("surface error: {e:?}");
                return;
            }
        };

        let view = output
            .texture
            .create_view(&wgpu::TextureViewDescriptor::default());

        let mut encoder = self
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("frame"),
            });

        {
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("main"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &view,
                    resolve_target: None,
                    ops: wgpu::Operations {
                        load: wgpu::LoadOp::Clear(wgpu::Color {
                            r: 0.02,
                            g: 0.02,
                            b: 0.06,
                            a: 1.0,
                        }),
                        store: wgpu::StoreOp::Store,
                    },
                })],
                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                    view: &self.depth_view,
                    depth_ops: Some(wgpu::Operations {
                        load: wgpu::LoadOp::Clear(1.0),
                        store: wgpu::StoreOp::Store,
                    }),
                    stencil_ops: None,
                }),
                ..Default::default()
            });

            pass.set_pipeline(&self.pipeline);
            pass.set_bind_group(0, &self.camera_bind_group, &[]);

            // 1. Track surface (track.png)
            pass.set_bind_group(1, &self.tex_track, &[]);
            self.draw_mesh(&mut pass, &self.track_surface);

            // 2. Track lines (white — colored)
            pass.set_bind_group(1, &self.tex_white, &[]);
            self.draw_mesh(&mut pass, &self.track_lines);

            // 3. Tap notes (note.png)
            pass.set_bind_group(1, &self.tex_note, &[]);
            self.draw_mesh(&mut pass, &self.note_taps);

            // 4. Hold notes (note_hold.png)
            pass.set_bind_group(1, &self.tex_hold, &[]);
            self.draw_mesh(&mut pass, &self.note_holds);

            // 5. Arcs + sky notes (white — colored)
            pass.set_bind_group(1, &self.tex_white, &[]);
            self.draw_mesh(&mut pass, &self.note_other);
        }

        self.queue.submit(std::iter::once(encoder.finish()));
        output.present();
    }

    fn draw_mesh<'a>(&'a self, pass: &mut wgpu::RenderPass<'a>, mesh: &'a MeshBuffer) {
        if mesh.index_count == 0 {
            return;
        }
        pass.set_vertex_buffer(0, mesh.vertex.slice(..));
        pass.set_index_buffer(mesh.index.slice(..), wgpu::IndexFormat::Uint32);
        pass.draw_indexed(0..mesh.index_count, 0, 0..1);
    }
}

fn create_depth_texture(device: &wgpu::Device, width: u32, height: u32) -> wgpu::TextureView {
    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("depth"),
        size: wgpu::Extent3d {
            width,
            height,
            depth_or_array_layers: 1,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: wgpu::TextureFormat::Depth32Float,
        usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
        view_formats: &[],
    });
    texture.create_view(&wgpu::TextureViewDescriptor::default())
}

