/// Static geometry split by texture.
pub struct TrackGeometry {
    pub surface: Mesh, // track.png
    pub lines: Mesh,   // white (colored) — dividers + judgment line
}

/// Dynamic note geometry split by texture.
pub struct NoteGeometry {
    pub taps: Mesh,  // note.png
    pub holds: Mesh, // note_hold.png
    pub other: Mesh, // white (colored) — arcs, sky notes
}

/// Build static track geometry, split by texture.
