/// Update note geometry for the current frame.
pub fn update_notes(&mut self, chart: &Chart, clock: &GameClock, current_time: Ms) {
    let geo = super::track::build_note_geometry(chart, clock, current_time);
    self.upload_mesh(&geo.taps, "note_taps");
    self.upload_mesh(&geo.holds, "note_holds");
    self.upload_mesh(&geo.other, "note_other");
}

fn upload_mesh(&mut self, mesh: &(Vec<Vertex>, Vec<u32>), which: &str) {
    let (verts, idxs) = mesh;
    let buf = match which {
        "note_taps" => &mut self.note_taps,
        "note_holds" => &mut self.note_holds,
        "note_other" => &mut self.note_other,
        _ => return,
    };
    buf.index_count = idxs.len() as u32;

    if verts.is_empty() {
        return;
    }

    let vert_bytes = bytemuck::cast_slice(verts);
    let idx_bytes = bytemuck::cast_slice(idxs);

    if vert_bytes.len() as u64 > buf.vertex.size() {
        buf.vertex = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some(&format!("{which}_verts")),
            contents: vert_bytes,
            usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
        });
    } else {
        self.queue.write_buffer(&buf.vertex, 0, vert_bytes);
    }

    if idx_bytes.len() as u64 > buf.index.size() {
        buf.index = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some(&format!("{which}_idxs")),
            contents: idx_bytes,
            usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,

