    };
    let x = arc.x1 + (arc.x2 - arc.x1) * t;
    let y = arc.y1 + (arc.y2 - arc.y1) * t;

    let wx = arc_x_to_world(x);
    let wy = arc_y_to_world(y);

    // Sky note: diamond shape in the X-Y plane facing the camera.
