// Hit effects: hit_pure.png / hit_far.png sprite at judgment line
// Displayed as a billboard-like quad above the judgment line.
use crate::judgment::Grade;
const EFFECT_DURATION_MS: Ms = 300;
for eff in hit_effects {
    let age = current_time - eff.time_ms;
    if age < 0 || age > EFFECT_DURATION_MS {
        continue;
    }
    let t = age as f32 / EFFECT_DURATION_MS as f32;
    let alpha = 1.0 - t;
    let scale = 1.0 + t * 0.5; // slight expand

    let cx = lane_to_x(eff.lane as f32);
    let size = LANE_WIDTH * 0.6 * scale;
    let hs = size * 0.5;
    let y = 0.5; // float above track

    // Tint by grade
    let color = match eff.grade {
        Grade::PureMax => [0.8, 0.9, 1.0, alpha],
        Grade::Pure    => [0.7, 0.8, 1.0, alpha],
        Grade::Far     => [0.9, 0.7, 0.9, alpha],
        Grade::Lost    => [0.5, 0.5, 0.5, alpha],
    };

    // Quad in X-Y plane at z=0 (judgment line), facing camera
    push_quad_uv(
        &mut effects.0,
        &mut effects.1,
        [
            [cx - hs, y, -hs * 0.3],
            [cx + hs, y, -hs * 0.3],
            [cx + hs, y + size, -hs * 0.3],
            [cx - hs, y + size, -hs * 0.3],
        ],
